 1→import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
 2→import { ConfigService } from '@nestjs/config';
 3→import * as jose from 'jose';
 4→
 5→const KID = 'cipherbox-identity-1';
 6→/** RSA private JWK fields to strip when creating the public JWK */
 7→const RSA_PRIVATE_FIELDS = new Set(['d', 'p', 'q', 'dp', 'dq', 'qi']);
 8→
 9→@Injectable()
10→export class JwtIssuerService implements OnModuleInit {
11→  private readonly logger = new Logger(JwtIssuerService.name);
12→  private privateKey!: jose.CryptoKey | jose.KeyObject;
13→  private publicJwk!: jose.JWK;
14→
15→  constructor(private config: ConfigService) {}
16→
17→  async onModuleInit(): Promise<void> {
18→    const pemKey = this.config.get<string>('IDENTITY_JWT_PRIVATE_KEY');
19→
20→    if (pemKey) {
21→      this.logger.log('Loading RS256 identity keypair from IDENTITY_JWT_PRIVATE_KEY env var');
22→      // Env var is base64-encoded PEM (multiline PEM doesn't work in .env files)
23→      const pem = Buffer.from(pemKey, 'base64').toString('utf8');
24→      this.privateKey = await jose.importPKCS8(pem, 'RS256', { extractable: true });
25→      // Derive public JWK from private key (strip private fields)
26→      const privateJwk = await jose.exportJWK(this.privateKey);
27→      const publicJwkData = Object.fromEntries(
28→        Object.entries(privateJwk).filter(([k]) => !RSA_PRIVATE_FIELDS.has(k))
29→      );
30→      this.publicJwk = { ...publicJwkData, kid: KID, alg: 'RS256', use: 'sig' };
31→    } else if (this.config.get<string>('NODE_ENV') === 'production') {
32→      throw new Error(
33→        'IDENTITY_JWT_PRIVATE_KEY must be set in production. ' +
34→          'Generate with: openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048'
35→      );
36→    } else {
37→      this.logger.warn(
38→        'IDENTITY_JWT_PRIVATE_KEY not set — generating ephemeral RS256 keypair (dev/staging only)'
39→      );
40→      const { publicKey, privateKey } = await jose.generateKeyPair('RS256', {
41→        modulusLength: 2048,
42→      });
43→      this.privateKey = privateKey;
44→      const jwk = await jose.exportJWK(publicKey);
45→      this.publicJwk = { ...jwk, kid: KID, alg: 'RS256', use: 'sig' };
46→    }
47→
48→    this.logger.log(`Identity JWKS ready (kid=${KID})`);
49→  }
50→
51→  /**
52→   * Sign a CipherBox identity JWT for Web3Auth custom verifier consumption.
53→   *
54→   * Claims: iss=cipherbox, aud=web3auth, sub=userId, email (optional), exp=5min
55→   */
56→  async signIdentityJwt(userId: string, email?: string): Promise<string> {
57→    const claims: Record<string, unknown> = { sub: userId };
58→    if (email) {
59→      claims.email = email;
60→    }
61→    return new jose.SignJWT(claims)
62→      .setProtectedHeader({ alg: 'RS256', kid: KID })
63→      .setIssuer('cipherbox')
64→      .setAudience('web3auth')
65→      .setIssuedAt()
66→      .setExpirationTime('5m')
67→      .sign(this.privateKey);
68→  }
69→
70→  /**
71→   * Return JWKS data for the /.well-known/jwks.json endpoint.
72→   */
73→  getJwksData(): { keys: jose.JWK[] } {
74→    return { keys: [this.publicJwk] };
75→  }
76→}
