229→  /**
230→   * Permanently delete a user account and all associated data.
231→   *
232→   * 1. Unpins all IPFS content from the local Kubo node (best-effort)
233→   * 2. Deletes the user row — ON DELETE CASCADE handles cleanup of
234→   *    auth_methods, refresh_tokens, vaults, pinned_cids, folder_ipns,
235→   *    ipns_republish_schedule, shares, share_keys, and share_invites.
236→   */
237→  async deleteAccount(userId: string): Promise<{ success: boolean }> {
238→    // Fetch all pinned CIDs before cascade deletes the records
239→    const pinnedCids = await this.pinnedCidRepository.find({
240→      where: { userId },
241→      select: ['cid'],
242→    });
243→
244→    // Unpin all content from Kubo (best-effort, don't block deletion on failure)
245→    if (pinnedCids.length > 0) {
246→      const results = await Promise.allSettled(
247→        pinnedCids.map((pin) => this.ipfsProvider.unpinFile(pin.cid))
248→      );
249→      const failed = results.filter((r) => r.status === 'rejected').length;
250→      this.logger.log(
251→        `Unpinned ${pinnedCids.length - failed}/${pinnedCids.length} CIDs for user ${userId}` +
252→          (failed > 0 ? ` (${failed} failed)` : '')
253→      );
254→    }
255→
256→    // Delete user row — cascade handles all related DB records
257→    const result = await this.userRepository.delete(userId);
258→    if (result.affected === 0) {
259→      throw new BadRequestException('Account not found');
260→    }
261→    this.logger.log(`Account deleted: userId=${userId}`);
262→    return { success: true };
263→  }
