183→  /**
184→   * Verify a CipherBox-issued JWT for Core Kit login flow.
185→   * Since we are the identity provider, we verify against our own JWKS.
186→   */
187→  private async verifyCipherBoxJwt(
188→    idToken: string
189→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
190→    try {
191→      const jwksData = this.jwtIssuerService.getJwksData();
192→      const jwks = jose.createLocalJWKSet(jwksData);
193→      const { payload } = await jose.jwtVerify(idToken, jwks, {
194→        issuer: 'cipherbox',
195→        audience: 'web3auth',
196→        algorithms: ['RS256'],
197→      });
198→      return {
199→        sub: payload.sub,
200→        verifierId: payload.sub,
201→        email: payload.email as string | undefined,
202→      };
203→    } catch (error) {
204→      this.logger.warn(
205→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
206→      );
207→      throw new UnauthorizedException('Invalid CipherBox identity token');
208→    }
209→  }
