 39→  const { syncStatus } = useCoreKit();
 40→  const {
 41→    accessToken,
 42→    isAuthenticated,
 43→    lastAuthMethod,
 44→    userEmail,
 45→    setAccessToken,
 46→    setLastAuthMethod,
 47→    setUserEmail,
 48→    setVaultKeypair,
 49→    logout: clearAuthState,
