  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useDeviceApproval, type ApprovalStatus } from '../../hooks/useDeviceApproval';
  3→import { useAuthStore } from '../../stores/auth.store';
  4→
  5→type DeviceWaitingScreenProps = {
  6→  onRecoveryFallback: () => void;
  7→  onApprovalComplete: () => void;
  8→};
  9→
 10→const APPROVAL_TTL_MS = 5 * 60 * 1000; // 5 minutes
 11→const COUNTDOWN_WARNING_MS = 3 * 60 * 1000; // 3 minutes remaining
 12→
 13→/**
 14→ * Full-screen waiting component shown when a new device is in
 15→ * REQUIRED_SHARE state. Creates a bulletin board approval request
 16→ * and polls for a response from an existing device.
 17→ *
 18→ * Displays a spinner, countdown timer, and a fallback link to
 19→ * use a recovery phrase instead.
 20→ */
 21→export function DeviceWaitingScreen({
 22→  onRecoveryFallback,
 23→  onApprovalComplete,
 24→}: DeviceWaitingScreenProps) {
 25→  const { requestApproval, cancelRequest, approvalStatus, approvalError } = useDeviceApproval();
 26→  const accessToken = useAuthStore((s) => s.accessToken);
 27→
 28→  const [countdown, setCountdown] = useState(APPROVAL_TTL_MS);
 29→  const startTimeRef = useRef<number>(Date.now());
 30→  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);
 31→  const requestFiredRef = useRef(false);
 32→
 33→  // Start the approval request once the temp access token is available.
 34→  // The token is obtained asynchronously in loginWithGoogle/Email/Wallet
 35→  // AFTER syncStatus() sets isRequiredShare=true, so this component may
 36→  // mount before the token is stored. We wait for it to avoid a 401.
 37→  useEffect(() => {
 38→    if (!accessToken || requestFiredRef.current) return;
 39→    requestFiredRef.current = true;
 40→
 41→    // Clear any existing interval before starting a new one (defensive against retry re-trigger)
 42→    if (countdownRef.current) {
 43→      clearInterval(countdownRef.current);
 44→    }
 45→
 46→    startTimeRef.current = Date.now();
 47→    requestApproval();
 48→
 49→    // Countdown timer
 50→    countdownRef.current = setInterval(() => {
 51→      const elapsed = Date.now() - startTimeRef.current;
 52→      const remaining = Math.max(0, APPROVAL_TTL_MS - elapsed);
 53→      setCountdown(remaining);
 54→    }, 1000);
 55→  }, [accessToken, requestApproval]);
 56→
 57→  // Cleanup on unmount: clear countdown timer and cancel pending request
 58→  useEffect(() => {
 59→    return () => {
 60→      if (countdownRef.current) {
 61→        clearInterval(countdownRef.current);
 62→      }
 63→      cancelRequest();
 64→    };
 65→  }, [cancelRequest]);
 66→
 67→  // Auto-complete when approval succeeds
 68→  useEffect(() => {
 69→    if (approvalStatus === 'approved') {
 70→      onApprovalComplete();
 71→    }
 72→  }, [approvalStatus, onApprovalComplete]);
 73→
 74→  const handleRetry = useCallback(() => {
 75→    requestFiredRef.current = false;
 76→    startTimeRef.current = Date.now();
 77→    setCountdown(APPROVAL_TTL_MS);
 78→    requestApproval();
 79→  }, [requestApproval]);
 80→
 81→  const minutes = Math.floor(countdown / 60000);
 82→  const seconds = Math.floor((countdown % 60000) / 1000);
 83→  const timeDisplay = `${minutes}:${seconds.toString().padStart(2, '0')}`;
 84→  const isWarning = countdown <= COUNTDOWN_WARNING_MS && countdown > 0;
 85→
 86→  return (
 87→    <div className="device-waiting" data-testid="device-waiting">
 88→      <div className="device-waiting-card">
 89→        <h2 className="device-waiting-title">{'// waiting for device approval'}</h2>
 90→
 91→        {renderContent(approvalStatus, {
 92→          timeDisplay,
 93→          isWarning,
 94→          countdown,
 95→          approvalError,
 96→          onRecoveryFallback,
 97→          handleRetry,
 98→        })}
 99→      </div>
100→    </div>
101→  );
102→}
103→
104→function renderContent(
105→  status: ApprovalStatus,
106→  props: {
107→    timeDisplay: string;
108→    isWarning: boolean;
109→    countdown: number;
110→    approvalError: string | null;
111→    onRecoveryFallback: () => void;
112→    handleRetry: () => void;
113→  }
114→) {
115→  const { timeDisplay, isWarning, countdown, approvalError, onRecoveryFallback, handleRetry } =
116→    props;
117→
118→  if (status === 'denied') {
119→    return (
120→      <div className="device-waiting-content">
121→        <div
122→          className="device-waiting-status-message device-waiting-denied"
123→          data-testid="device-waiting-status"
124→        >
125→          Request was denied by another device.
126→        </div>
127→        <div className="device-waiting-actions">
128→          <button
129→            type="button"
130→            className="device-waiting-btn"
131→            onClick={handleRetry}
132→            data-testid="device-waiting-retry"
133→          >
134→            --retry
135→          </button>
136→          <button
137→            type="button"
138→            className="device-waiting-link"
139→            onClick={onRecoveryFallback}
140→            data-testid="device-waiting-recovery-link"
141→          >
142→            use recovery phrase instead
143→          </button>
144→        </div>
145→      </div>
146→    );
147→  }
148→
149→  if (status === 'expired') {
150→    return (
151→      <div className="device-waiting-content">
152→        <div
153→          className="device-waiting-status-message device-waiting-expired"
154→          data-testid="device-waiting-status"
155→        >
156→          Request expired. No device responded within the time limit.
157→        </div>
158→        <div className="device-waiting-actions">
159→          <button
160→            type="button"
161→            className="device-waiting-btn"
162→            onClick={handleRetry}
163→            data-testid="device-waiting-retry"
164→          >
165→            --retry
166→          </button>
167→          <button
168→            type="button"
169→            className="device-waiting-link"
170→            onClick={onRecoveryFallback}
171→            data-testid="device-waiting-recovery-link"
172→          >
173→            use recovery phrase instead
174→          </button>
175→        </div>
176→      </div>
177→    );
178→  }
179→
180→  if (status === 'error') {
181→    return (
182→      <div className="device-waiting-content">
183→        <div
184→          className="device-waiting-status-message device-waiting-error"
185→          data-testid="device-waiting-status"
186→        >
187→          {approvalError || 'An error occurred.'}
188→        </div>
189→        <div className="device-waiting-actions">
190→          <button
191→            type="button"
192→            className="device-waiting-btn"
193→            onClick={handleRetry}
194→            data-testid="device-waiting-retry"
195→          >
196→            --retry
197→          </button>
198→          <button
199→            type="button"
200→            className="device-waiting-link"
201→            onClick={onRecoveryFallback}
202→            data-testid="device-waiting-recovery-link"
203→          >
204→            use recovery phrase instead
205→          </button>
206→        </div>
207→      </div>
208→    );
209→  }
210→
211→  if (status === 'completing') {
212→    return (
213→      <div className="device-waiting-content">
214→        <span className="device-waiting-spinner" aria-hidden="true" />
215→        <p className="device-waiting-text">Approval received. Completing login...</p>
216→      </div>
217→    );
218→  }
219→
220→  // Default: requesting/pending
221→  return (
222→    <div className="device-waiting-content">
223→      <span className="device-waiting-spinner" aria-hidden="true" />
224→      <p className="device-waiting-text">
225→        Request sent to your other devices. Open CipherBox on an authorized device to approve this
226→        login.
227→      </p>
228→      <div
229→        className={`device-waiting-countdown ${isWarning ? 'warning' : ''}`}
230→        aria-label={`Time remaining: ${timeDisplay}`}
231→        data-testid="device-waiting-countdown"
232→      >
233→        {countdown > 0 ? timeDisplay : 'expired'}
234→      </div>
235→      <button
236→        type="button"
237→        className="device-waiting-link"
238→        onClick={onRecoveryFallback}
239→        data-testid="device-waiting-recovery-link"
240→      >
241→        use recovery phrase instead
242→      </button>
243→    </div>
244→  );
245→}
