  1→import { useCallback } from 'react';
  2→import BN from 'bn.js';
  3→import * as secp256k1 from '@noble/secp256k1';
  4→import { hexToBytes, bytesToHex } from '@cipherbox/crypto';
  5→import { useCoreKit } from './core-kit-provider';
  6→import { COREKIT_STATUS } from './core-kit';
  7→import { authApi } from '../api/auth';
  8→
  9→export type CoreKitLoginResult = 'logged_in' | 'required_share';
 10→
 11→export function useCoreKitAuth() {
 12→  const { coreKit, status, isLoggedIn, isInitialized, isRequiredShare, syncStatus } = useCoreKit();
 13→
 14→  /**
 15→   * Login with Google: Backend verifies Google idToken, issues CipherBox JWT,
 16→   * then we call loginWithJWT on Core Kit.
 17→   */
 18→  const loginWithGoogle = useCallback(
 19→    async (
 20→      googleIdToken: string
 21→    ): Promise<{
 22→      cipherboxJwt: string;
 23→      email?: string;
 24→      userId: string;
 25→      status: CoreKitLoginResult;
 26→    }> => {
 27→      if (!coreKit) throw new Error('Core Kit not initialized');
 28→
 29→      const { idToken: cipherboxJwt, userId, email } = await authApi.identityGoogle(googleIdToken);
 30→      const coreKitStatus = await doLoginWithCoreKit(coreKit, syncStatus, cipherboxJwt, userId);
 31→      return { cipherboxJwt, email, userId, status: coreKitStatus };
 32→    },
 33→    [coreKit, syncStatus]
 34→  );
 35→
 36→  /**
 37→   * Login with Email: Backend handles OTP send/verify, issues CipherBox JWT.
 38→   */
 39→  const loginWithEmailOtp = useCallback(
 40→    async (
 41→      email: string,
 42→      otp: string
 43→    ): Promise<{ cipherboxJwt: string; userId: string; status: CoreKitLoginResult }> => {
 44→      if (!coreKit) throw new Error('Core Kit not initialized');
 45→
 46→      const { idToken: cipherboxJwt, userId } = await authApi.identityEmailVerify(email, otp);
 47→      const coreKitStatus = await doLoginWithCoreKit(coreKit, syncStatus, cipherboxJwt, userId);
 48→      return { cipherboxJwt, userId, status: coreKitStatus };
 49→    },
 50→    [coreKit, syncStatus]
 51→  );
 52→
 53→  /**
 54→   * Login with Wallet: Backend verifies SIWE signature, issues CipherBox JWT,
 55→   * then we call loginWithJWT on Core Kit.
 56→   */
 57→  const loginWithWallet = useCallback(
 58→    async (
 59→      cipherboxJwt: string,
 60→      userId: string
 61→    ): Promise<{ cipherboxJwt: string; userId: string; status: CoreKitLoginResult }> => {
 62→      if (!coreKit) throw new Error('Core Kit not initialized');
 63→
 64→      const coreKitStatus = await doLoginWithCoreKit(coreKit, syncStatus, cipherboxJwt, userId);
 65→      return { cipherboxJwt, userId, status: coreKitStatus };
 66→    },
 67→    [coreKit, syncStatus]
 68→  );
 69→
 70→  /**
 71→   * Get vault keypair from Core Kit's exported TSS key.
 72→   */
 73→  const getVaultKeypair = useCallback(async (): Promise<{
 74→    publicKey: Uint8Array;
 75→    privateKey: Uint8Array;
 76→  } | null> => {
 77→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return null;
 78→
 79→    try {
 80→      console.log('[CoreKit] _UNSAFE_exportTssKey starting...');
 81→      console.time('[CoreKit] exportTssKey');
 82→      const privateKeyHex = await coreKit._UNSAFE_exportTssKey();
 83→      console.timeEnd('[CoreKit] exportTssKey');
 84→      console.log('[CoreKit] exportTssKey done, hex length:', privateKeyHex.length);
 85→      const privKeyHex = privateKeyHex.startsWith('0x') ? privateKeyHex.slice(2) : privateKeyHex;
 86→      const privateKey = hexToBytes(privKeyHex);
 87→      const publicKey = secp256k1.getPublicKey(privateKey, false); // uncompressed (65 bytes)
 88→      console.log('[CoreKit] keypair derived, pubkey hex length:', publicKey.length * 2);
 89→      return { publicKey, privateKey };
 90→    } catch (err) {
 91→      console.timeEnd('[CoreKit] exportTssKey');
 92→      console.error('[CoreKit] Failed to export TSS key:', err);
 93→      return null;
 94→    }
 95→  }, [coreKit]);
 96→
 97→  /**
 98→   * Get uncompressed public key hex for backend auth.
 99→   */
100→  const getPublicKeyHex = useCallback(async (): Promise<string | null> => {
101→    const keypair = await getVaultKeypair();
102→    if (!keypair) return null;
103→    return bytesToHex(keypair.publicKey);
104→  }, [getVaultKeypair]);
105→
106→  /**
107→   * Logout from Core Kit.
108→   */
109→  const logout = useCallback(async (): Promise<void> => {
110→    if (!coreKit) return;
111→    try {
112→      if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
113→        await coreKit.logout();
114→      }
115→    } catch (err) {
116→      console.error('[CoreKit] Logout error:', err);
117→    } finally {
118→      syncStatus();
119→    }
120→  }, [coreKit, syncStatus]);
121→
122→  return {
123→    status,
124→    isLoggedIn,
125→    isInitialized,
126→    isRequiredShare,
127→    loginWithGoogle,
128→    loginWithEmailOtp,
129→    loginWithWallet,
130→    getVaultKeypair,
131→    getPublicKeyHex,
132→    logout,
133→  };
134→}
135→
136→/**
137→ * Shared Core Kit login logic extracted as a standalone function
138→ * (not a hook method) to avoid re-creation on every render.
139→ *
140→ * Takes a CipherBox JWT and userId, calls loginWithJWT and commitChanges.
141→ * Returns 'logged_in' if device factor found, 'required_share' if MFA
142→ * is enabled but this device lacks a factor.
143→ */
144→async function doLoginWithCoreKit(
145→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
146→  coreKit: any,
147→  syncStatus: () => void,
148→  cipherboxJwt: string,
149→  userId: string
150→): Promise<CoreKitLoginResult> {
151→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
152→  const loginParams: any = {
153→    verifier: 'cipherbox-identity',
154→    verifierId: userId,
155→    idToken: cipherboxJwt,
156→  };
157→
158→  console.log('[CoreKit] loginWithJWT starting...', {
159→    verifier: loginParams.verifier,
160→    verifierId: userId,
161→  });
162→  console.time('[CoreKit] loginWithJWT');
163→  try {
164→    await coreKit.loginWithJWT(loginParams);
165→    console.timeEnd('[CoreKit] loginWithJWT');
166→    console.log('[CoreKit] loginWithJWT completed, status:', coreKit.status);
167→  } catch (err) {
168→    console.timeEnd('[CoreKit] loginWithJWT');
169→    console.error('[CoreKit] loginWithJWT FAILED:', err);
170→    throw err;
171→  }
172→
173→  // Handle status
174→  if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
175→    console.log('[CoreKit] commitChanges starting...');
176→    console.time('[CoreKit] commitChanges');
177→    try {
178→      await coreKit.commitChanges();
179→      console.timeEnd('[CoreKit] commitChanges');
180→      console.log('[CoreKit] commitChanges done');
181→    } catch (err) {
182→      console.timeEnd('[CoreKit] commitChanges');
183→      console.error('[CoreKit] commitChanges FAILED:', err);
184→    }
185→
186→    // DEBUG: Test exportTssKey in isolation BEFORE triggering React updates
187→    console.log('[CoreKit] DEBUG: testing exportTssKey in isolation...');
188→    console.time('[CoreKit] exportTssKey-test');
189→    try {
190→      const testKey = await coreKit._UNSAFE_exportTssKey();
191→      console.timeEnd('[CoreKit] exportTssKey-test');
192→      console.log('[CoreKit] exportTssKey-test succeeded, length:', testKey.length);
193→    } catch (err) {
194→      console.timeEnd('[CoreKit] exportTssKey-test');
195→      console.error('[CoreKit] exportTssKey-test FAILED:', err);
196→    }
197→
198→    console.log('[CoreKit] calling syncStatus...');
199→    syncStatus();
200→    console.log('[CoreKit] syncStatus called, returning logged_in');
201→    return 'logged_in';
202→  }
203→
204→  if (coreKit.status === COREKIT_STATUS.REQUIRED_SHARE) {
205→    // Bug fix: Web3Auth's handleExistingUser() does NOT auto-check localStorage
206→    // for the device factor when the hashedShare has been deleted (post-MFA).
207→    // We must manually retrieve and input the device factor if it exists.
208→    console.log('[CoreKit] REQUIRED_SHARE — checking for device factor in localStorage...');
209→    try {
210→      const deviceFactorHex = await coreKit.getDeviceFactor();
211→      if (deviceFactorHex) {
212→        console.log('[CoreKit] Device factor found in localStorage, auto-inputting...');
213→        await coreKit.inputFactorKey(new BN(deviceFactorHex, 'hex'));
214→
215→        if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
216→          console.log('[CoreKit] Device factor accepted — now LOGGED_IN');
217→          try {
218→            await coreKit.commitChanges();
219→          } catch (err) {
220→            console.error('[CoreKit] commitChanges after device factor FAILED:', err);
221→          }
222→          syncStatus();
223→          return 'logged_in';
224→        }
225→      } else {
226→        console.log('[CoreKit] No device factor in localStorage — true REQUIRED_SHARE');
227→      }
228→    } catch (err) {
229→      console.warn('[CoreKit] Device factor check failed (expected on new device):', err);
230→    }
231→
232→    syncStatus();
233→    return 'required_share';
234→  }
235→
236→  throw new Error(`Unexpected Core Kit status: ${coreKit.status}`);
237→}
