  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
  5→  Delete,
  6→  Body,
  7→  Param,
  8→  UseGuards,
  9→  Request,
 10→  ParseUUIDPipe,
 11→} from '@nestjs/common';
 12→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
 13→import { ThrottlerGuard, Throttle } from '@nestjs/throttler';
 14→import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
 15→import { AllowScope } from '../auth/decorators/allow-scope.decorator';
 16→import { DeviceApprovalService } from './device-approval.service';
 17→import { CreateApprovalDto } from './dto/create-approval.dto';
 18→import { RespondApprovalDto } from './dto/respond-approval.dto';
 19→import { RequestWithUser } from '../common/types';
 20→
 21→@ApiTags('device-approval')
 22→@ApiBearerAuth()
 23→@AllowScope('device-approval')
 24→@UseGuards(JwtAuthGuard, ThrottlerGuard)
 25→@Controller('device-approval')
 26→export class DeviceApprovalController {
 27→  constructor(private readonly deviceApprovalService: DeviceApprovalService) {}
 28→
 29→  @Post('request')
 30→  @Throttle({ default: { limit: 3, ttl: 60000 } })
 31→  @ApiOperation({
 32→    summary: 'Create device approval request',
 33→    description:
 34→      'New device creates an approval request with an ephemeral ' +
 35→      'public key for ECIES key exchange. Request expires after ' +
 36→      '5 minutes.',
 37→  })
 38→  @ApiResponse({
 39→    status: 201,
 40→    description: 'Approval request created',
 41→    schema: {
 42→      properties: {
 43→        requestId: { type: 'string', format: 'uuid' },
 44→      },
 45→    },
 46→  })
 47→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 48→  async createRequest(
 49→    @Request() req: RequestWithUser,
 50→    @Body() dto: CreateApprovalDto
 51→  ): Promise<{ requestId: string }> {
 52→    return this.deviceApprovalService.createRequest(req.user.id, dto);
 53→  }
 54→
 55→  @Get(':requestId/status')
 56→  @ApiOperation({
 57→    summary: 'Poll approval request status',
 58→    description:
 59→      'New device polls this endpoint to check if the request ' +
 60→      'has been approved, denied, or expired. Returns the ' +
 61→      'encrypted factor key on approval.',
 62→  })
 63→  @ApiResponse({
 64→    status: 200,
 65→    description: 'Approval status',
 66→    schema: {
 67→      properties: {
 68→        status: {
 69→          type: 'string',
 70→          enum: ['pending', 'approved', 'denied', 'expired'],
 71→        },
 72→        encryptedFactorKey: {
 73→          type: 'string',
 74→          nullable: true,
 75→          description: 'ECIES-encrypted factor key (hex)',
 76→        },
 77→      },
 78→    },
 79→  })
 80→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 81→  @ApiResponse({
 82→    status: 404,
 83→    description: 'Request not found',
 84→  })
 85→  async getStatus(
 86→    @Request() req: RequestWithUser,
 87→    @Param('requestId', ParseUUIDPipe) requestId: string
 88→  ): Promise<{ status: string; encryptedFactorKey?: string }> {
 89→    return this.deviceApprovalService.getStatus(requestId, req.user.id);
 90→  }
 91→
 92→  @Get('pending')
 93→  @ApiOperation({
 94→    summary: 'List pending approval requests',
 95→    description:
 96→      'Existing device fetches all non-expired pending approval ' +
 97→      'requests for the authenticated user.',
 98→  })
 99→  @ApiResponse({
100→    status: 200,
101→    description: 'List of pending approval requests',
102→    schema: {
103→      type: 'array',
104→      items: {
105→        properties: {
106→          requestId: { type: 'string', format: 'uuid' },
107→          deviceId: { type: 'string' },
108→          deviceName: { type: 'string' },
109→          ephemeralPublicKey: { type: 'string' },
110→          createdAt: { type: 'string', format: 'date-time' },
111→          expiresAt: { type: 'string', format: 'date-time' },
112→        },
113→      },
114→    },
115→  })
116→  @ApiResponse({ status: 401, description: 'Unauthorized' })
117→  async getPending(@Request() req: RequestWithUser): Promise<
118→    Array<{
119→      requestId: string;
120→      deviceId: string;
121→      deviceName: string;
122→      ephemeralPublicKey: string;
123→      createdAt: Date;
124→      expiresAt: Date;
125→    }>
126→  > {
127→    return this.deviceApprovalService.getPending(req.user.id);
128→  }
129→
130→  @Post(':requestId/respond')
131→  @ApiOperation({
132→    summary: 'Respond to approval request',
133→    description:
134→      'Existing device approves or denies an approval request. ' +
135→      'On approve, includes the ECIES-encrypted factor key.',
136→  })
137→  @ApiResponse({
138→    status: 200,
139→    description: 'Response recorded',
140→  })
141→  @ApiResponse({ status: 400, description: 'Already responded or expired' })
142→  @ApiResponse({ status: 401, description: 'Unauthorized' })
143→  @ApiResponse({ status: 404, description: 'Request not found' })
144→  async respond(
145→    @Request() req: RequestWithUser,
146→    @Param('requestId', ParseUUIDPipe) requestId: string,
147→    @Body() dto: RespondApprovalDto
148→  ): Promise<void> {
149→    return this.deviceApprovalService.respond(requestId, req.user.id, dto);
150→  }
151→
152→  @Delete(':requestId')
153→  @ApiOperation({
154→    summary: 'Cancel approval request',
155→    description:
156→      'New device cancels its own pending approval request ' +
157→      '(cleanup on navigation away or recovery phrase used).',
158→  })
159→  @ApiResponse({ status: 200, description: 'Request cancelled' })
160→  @ApiResponse({ status: 401, description: 'Unauthorized' })
161→  @ApiResponse({
162→    status: 404,
163→    description: 'Request not found or not pending',
164→  })
165→  async cancel(
166→    @Request() req: RequestWithUser,
167→    @Param('requestId', ParseUUIDPipe) requestId: string
168→  ): Promise<void> {
169→    return this.deviceApprovalService.cancel(requestId, req.user.id);
170→  }
171→}
