558→  /**
559→   * Test-only login that bypasses Core Kit entirely.
560→   * Guarded by TEST_LOGIN_SECRET env var — never available in production.
561→   *
562→   * Creates/finds user by email, generates a deterministic secp256k1 keypair,
563→   * and issues tokens. Returns the keypair so E2E tests can initialize vaults.
564→   */
565→  async testLogin(
566→    email: string,
567→    secret: string
568→  ): Promise<{
569→    accessToken: string;
570→    refreshToken: string;
571→    isNewUser: boolean;
572→    publicKeyHex: string;
573→    privateKeyHex: string;
574→  }> {
575→    // 1. Defense-in-depth: never allow in production regardless of env var
576→    const nodeEnv = this.configService.get<string>('NODE_ENV');
577→    if (nodeEnv === 'production') {
578→      throw new ForbiddenException('Test login is not available in production');
579→    }
580→
581→    // 2. Validate TEST_LOGIN_SECRET with timing-safe comparison
582→    const expectedSecret = this.configService.get<string>('TEST_LOGIN_SECRET');
583→    if (!expectedSecret) {
584→      throw new ForbiddenException('Test login is not enabled');
585→    }
586→    const secretBuf = Buffer.from(secret);
587→    const expectedBuf = Buffer.from(expectedSecret);
588→    if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
589→      throw new UnauthorizedException('Invalid test login secret');
590→    }
591→
592→    // 2. Generate deterministic secp256k1 keypair from email
593→    const { publicKeyHex, privateKeyHex } = this.generateDeterministicKeypair(email);
594→
595→    // 3. Find or create user by email (hash-based lookup)
596→    const normalizedEmail = email.toLowerCase().trim();
597→    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);
598→
599→    const existingMethod = await this.authMethodRepository.findOne({
600→      where: { type: 'email', identifierHash },
601→      relations: ['user'],
602→    });
603→
604→    let user: User;
605→    let isNewUser = false;
606→
607→    if (existingMethod) {
608→      user = existingMethod.user;
609→      // Update publicKey to match deterministic keypair (may differ from Core Kit key)
610→      if (user.publicKey !== publicKeyHex) {
611→        user.publicKey = publicKeyHex;
612→        await this.userRepository.save(user);
613→      }
614→      existingMethod.lastUsedAt = new Date();
615→      await this.authMethodRepository.save(existingMethod);
616→    } else {
617→      isNewUser = true;
618→      user = await this.userRepository.save({ publicKey: publicKeyHex });
619→      await this.authMethodRepository.save({
620→        userId: user.id,
621→        type: 'email',
622→        identifier: identifierHash,
623→        identifierHash,
624→        identifierDisplay: this.siweService.truncateEmail(normalizedEmail),
625→        lastUsedAt: new Date(),
626→      });
627→    }
628→
629→    // 4. Issue tokens
630→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
631→
632→    this.logger.log(`Test login: userId=${user.id}, isNew=${isNewUser}`);
633→
634→    return {
635→      accessToken: tokens.accessToken,
636→      refreshToken: tokens.refreshToken,
637→      isNewUser,
638→      publicKeyHex,
639→      privateKeyHex,
640→    };
641→  }
642→
643→  /**
644→   * Generate a deterministic secp256k1 keypair from an email address.
645→   * Same email always produces the same keypair, enabling consistent
646→   * vault encryption across test runs.
647→   */
648→  private generateDeterministicKeypair(email: string): {
649→    publicKeyHex: string;
650→    privateKeyHex: string;
651→  } {
652→    // Derive 32-byte private key from email via SHA-256
653→    const seed = createHash('sha256')
654→      .update(`cipherbox-test-keypair:${email.toLowerCase().trim()}`)
655→      .digest();
656→
657→    // Ensure the seed is a valid secp256k1 private key (must be in [1, n-1])
658→    const n = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
659→    let keyInt = BigInt('0x' + seed.toString('hex'));
660→    keyInt = (keyInt % (n - 1n)) + 1n;
661→    const privateKeyHex = keyInt.toString(16).padStart(64, '0');
662→
663→    const ecdh = createECDH('secp256k1');
664→    ecdh.setPrivateKey(Buffer.from(privateKeyHex, 'hex'));
665→    const publicKeyHex = ecdh.getPublicKey().toString('hex'); // 65 bytes uncompressed
666→
667→    return { publicKeyHex, privateKeyHex };
668→  }
669→}
