  1→import { Injectable, UnauthorizedException } from '@nestjs/common';
  2→import { JwtService } from '@nestjs/jwt';
  3→import { InjectRepository } from '@nestjs/typeorm';
  4→import { Repository, IsNull } from 'typeorm';
  5→import * as argon2 from 'argon2';
  6→import { randomBytes } from 'crypto';
  7→import { RefreshToken } from '../entities/refresh-token.entity';
  8→
  9→interface TokenPair {
 10→  accessToken: string;
 11→  /** Empty string when skipRefreshToken is set (falsy, safe for conditional checks) */
 12→  refreshToken: string;
 13→}
 14→
 15→interface CreateTokenOptions {
 16→  /** Restrict token to specific API scopes (e.g., ['device-approval']) */
 17→  scope?: string[];
 18→  /** Skip refresh token generation (for temp auth flows) */
 19→  skipRefreshToken?: boolean;
 20→}
 21→
 22→@Injectable()
 23→export class TokenService {
 24→  private readonly REFRESH_TOKEN_EXPIRY_DAYS = 7;
 25→
 26→  constructor(
 27→    private jwtService: JwtService,
 28→    @InjectRepository(RefreshToken)
 29→    private refreshTokenRepo: Repository<RefreshToken>
 30→  ) {}
 31→
 32→  async createTokens(
 33→    userId: string,
 34→    publicKey: string,
 35→    options?: CreateTokenOptions
 36→  ): Promise<TokenPair> {
 37→    // Generate access token (include scope claim if restricted)
 38→    const payload: Record<string, unknown> = { sub: userId, publicKey };
 39→    if (options?.scope) {
 40→      payload.scope = options.scope;
 41→    }
 42→    const accessToken = this.jwtService.sign(payload, { expiresIn: '15m' });
 43→
 44→    // Skip refresh token for temp auth (scoped tokens should not be refreshable)
 45→    if (options?.skipRefreshToken) {
 46→      return { accessToken, refreshToken: '' };
 47→    }
 48→
 49→    // Generate refresh token
 50→    const refreshToken = randomBytes(32).toString('hex');
 51→    const tokenHash = await argon2.hash(refreshToken);
 52→
 53→    // Calculate expiry date
 54→    const expiresAt = new Date();
 55→    expiresAt.setDate(expiresAt.getDate() + this.REFRESH_TOKEN_EXPIRY_DAYS);
 56→
 57→    // Save to database with prefix for O(1) lookup
 58→    const tokenPrefix = refreshToken.substring(0, 16);
 59→    await this.refreshTokenRepo.save({
 60→      userId,
 61→      tokenHash,
 62→      tokenPrefix,
 63→      expiresAt,
 64→    });
 65→
 66→    return { accessToken, refreshToken };
 67→  }
 68→
 69→  async rotateRefreshToken(
 70→    oldRefreshToken: string,
 71→    userId: string,
 72→    publicKey: string
 73→  ): Promise<TokenPair> {
 74→    // Find candidate tokens by prefix for O(1) lookup instead of O(N) Argon2 scan
 75→    const prefix = oldRefreshToken.substring(0, 16);
 76→    const tokens = await this.refreshTokenRepo.find({
 77→      where: {
 78→        userId,
 79→        tokenPrefix: prefix,
 80→        revokedAt: IsNull(),
 81→      },
 82→    });
 83→
 84→    // Find matching token
 85→    let validToken: RefreshToken | null = null;
 86→    for (const token of tokens) {
 87→      try {
 88→        if (await argon2.verify(token.tokenHash, oldRefreshToken)) {
 89→          validToken = token;
 90→          break;
 91→        }
 92→      } catch {
 93→        // argon2.verify throws on invalid hash format, continue checking
 94→        continue;
 95→      }
 96→    }
 97→
 98→    if (!validToken) {
 99→      throw new UnauthorizedException('Invalid refresh token');
100→    }
101→
102→    if (validToken.expiresAt < new Date()) {
103→      // Revoke expired token
104→      validToken.revokedAt = new Date();
105→      await this.refreshTokenRepo.save(validToken);
106→      throw new UnauthorizedException('Refresh token expired');
107→    }
108→
109→    // Revoke old token
110→    validToken.revokedAt = new Date();
111→    await this.refreshTokenRepo.save(validToken);
112→
113→    // Create new tokens
114→    return this.createTokens(userId, publicKey);
115→  }
116→
117→  async revokeAllUserTokens(userId: string): Promise<void> {
118→    await this.refreshTokenRepo.update({ userId, revokedAt: IsNull() }, { revokedAt: new Date() });
119→  }
120→
121→  async revokeToken(tokenId: string): Promise<void> {
122→    await this.refreshTokenRepo.update(
123→      { id: tokenId, revokedAt: IsNull() },
124→      { revokedAt: new Date() }
125→    );
126→  }
127→}
