17→@Injectable()
18→export class JwtStrategy extends PassportStrategy(Strategy) {
19→  constructor(
20→    configService: ConfigService,
21→    @InjectRepository(User)
22→    private userRepository: Repository<User>
23→  ) {
24→    const secret = configService.get<string>('JWT_SECRET');
25→    if (!secret) {
26→      throw new Error('JWT_SECRET environment variable is not set');
27→    }
28→    super({
29→      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
30→      ignoreExpiration: false,
31→      secretOrKey: secret,
32→    });
33→  }
34→
35→  async validate(payload: JwtPayload): Promise<User & { scope?: string[] }> {
36→    const user = await this.userRepository.findOne({
37→      where: { id: payload.sub },
38→    });
39→
40→    if (!user) {
41→      throw new UnauthorizedException('User not found');
42→    }
43→
44→    // Attach scope from JWT payload so guards can enforce restrictions
45→    return Object.assign(user, payload.scope ? { scope: payload.scope } : {});
46→  }
47→}
