 1→import { ExecutionContext, ForbiddenException, Injectable } from '@nestjs/common';
 2→import { Reflector } from '@nestjs/core';
 3→import { AuthGuard } from '@nestjs/passport';
 4→
 5→@Injectable()
 6→export class JwtAuthGuard extends AuthGuard('jwt') {
 7→  constructor(private reflector: Reflector) {
 8→    super();
 9→  }
10→
11→  async canActivate(context: ExecutionContext): Promise<boolean> {
12→    // Standard JWT validation (sets req.user via JwtStrategy.validate)
13→    const result = await super.canActivate(context);
14→    if (!result) return false;
15→
16→    // Check scope restrictions on the authenticated token
17→    const request = context.switchToHttp().getRequest();
18→    const scope = request.user?.scope as string[] | undefined;
19→
20→    // No scope = full access token, allow everything
21→    if (!scope || scope.length === 0) return true;
22→
23→    // Scoped token: check if route allows this scope via @AllowScope()
24→    const allowedScopes = this.reflector.getAllAndOverride<string[]>('allowedScopes', [
25→      context.getHandler(),
26→      context.getClass(),
27→    ]);
28→
29→    // Route not decorated with @AllowScope → deny scoped tokens
30→    if (!allowedScopes) {
31→      throw new ForbiddenException('Insufficient token scope');
32→    }
33→
34→    // Check if token scope intersects with allowed scopes
35→    if (!scope.some((s) => allowedScopes.includes(s))) {
36→      throw new ForbiddenException('Insufficient token scope');
37→    }
38→
39→    return true;
40→  }
41→}
