 43→export const authApi = {
 44→  /**
 45→   * Authenticate user with Web3Auth ID token.
 46→   * Backend verifies the idToken with appropriate JWKS endpoint based on loginType.
 47→   * Refresh token is stored in HTTP-only cookie automatically.
 48→   */
 49→  login: async (data: LoginRequest): Promise<LoginResponse> => {
 50→    const response = await apiClient.post<LoginResponse>('/auth/login', data);
 51→    return response.data;
 52→  },
 53→
 54→  /**
 55→   * Refresh access token using HTTP-only refresh token cookie.
 56→   * The refresh token is automatically sent via withCredentials: true.
 57→   * New refresh token is set in HTTP-only cookie by the backend.
 58→   */
 59→  refresh: async (): Promise<TokenResponse> => {
 60→    const response = await apiClient.post<TokenResponse>('/auth/refresh');
 61→    return response.data;
 62→  },
 63→
 64→  /**
 65→   * Logout and invalidate refresh token.
 66→   * Clears HTTP-only cookie on backend.
 67→   */
 68→  logout: async (): Promise<void> => {
 69→    await apiClient.post('/auth/logout');
 70→  },
 71→
 72→  /**
 73→   * Get all linked auth methods for the current user.
 74→   */
 75→  getMethods: async (): Promise<AuthMethod[]> => {
 76→    const response = await apiClient.get<AuthMethod[]>('/auth/methods');
 77→    return response.data;
 78→  },
 79→
 80→  /**
 81→   * Link a new auth method to the current user account.
 82→   * The new auth method's publicKey must match the user's publicKey
 83→   * (via Web3Auth group connections).
 84→   */
 85→  linkMethod: async (data: LinkMethodRequest): Promise<AuthMethod[]> => {
 86→    const response = await apiClient.post<AuthMethod[]>('/auth/link', data);
 87→    return response.data;
 88→  },
 89→
 90→  /**
 91→   * Unlink an auth method from the current user account.
 92→   * Cannot unlink the last remaining auth method.
 93→   */
 94→  unlinkMethod: async (methodId: string): Promise<void> => {
 95→    await apiClient.post('/auth/unlink', { methodId });
 96→  },
 97→
 98→  /**
 99→   * Permanently delete the authenticated user's account.
100→   * Requires confirmation string "DELETE".
101→   */
102→  deleteAccount: async (): Promise<void> => {
103→    await apiClient.delete('/auth/account', { data: { confirmation: 'DELETE' } });
104→  },
105→
106→  // --- CipherBox Identity Provider endpoints (Plan 12-01) ---
107→
108→  /** Get CipherBox identity JWT via Google OAuth token */
109→  identityGoogle: async (
110→    googleIdToken: string,
111→    intent?: 'login' | 'link'
112→  ): Promise<IdentityTokenResponse> => {
113→    const response = await apiClient.post<IdentityTokenResponse>('/auth/identity/google', {
114→      idToken: googleIdToken,
115→      ...(intent && { intent }),
116→    });
117→    return response.data;
118→  },
119→
120→  /** Send email OTP */
121→  identityEmailSendOtp: async (email: string): Promise<{ success: boolean }> => {
122→    const response = await apiClient.post<{ success: boolean }>('/auth/identity/email/send-otp', {
123→      email,
124→    });
125→    return response.data;
126→  },
127→
128→  /** Verify email OTP and get CipherBox identity JWT */
129→  identityEmailVerify: async (
130→    email: string,
131→    otp: string,
132→    intent?: 'login' | 'link'
133→  ): Promise<IdentityTokenResponse> => {
134→    const response = await apiClient.post<IdentityTokenResponse>(
135→      '/auth/identity/email/verify-otp',
136→      {
137→        email,
138→        otp,
139→        ...(intent && { intent }),
140→      }
141→    );
142→    return response.data;
143→  },
144→
145→  /** Get a SIWE nonce for wallet login */
146→  identityWalletNonce: async (): Promise<{ nonce: string }> => {
147→    const response = await apiClient.get<{ nonce: string }>('/auth/identity/wallet/nonce');
148→    return response.data;
149→  },
150→
151→  /** Verify SIWE wallet signature and get CipherBox identity JWT */
152→  identityWalletVerify: async (data: {
153→    message: string;
154→    signature: string;
155→  }): Promise<IdentityTokenResponse> => {
156→    const response = await apiClient.post<IdentityTokenResponse>('/auth/identity/wallet', data);
157→    return response.data;
158→  },
159→};
