  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useVaultStore } from '../stores/vault.store';
  9→import { useFolderStore } from '../stores/folder.store';
 10→import { useSyncStore } from '../stores/sync.store';
 11→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 12→import { useMfaStore } from '../stores/mfa.store';
 13→import {
 14→  initializeVault,
 15→  encryptVaultKeys,
 16→  decryptVaultKeys,
 17→  deriveIpnsName,
 18→  hexToBytes,
 19→  bytesToHex,
 20→} from '@cipherbox/crypto';
 21→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 22→import { detectDeviceInfo } from '../lib/device/info';
 23→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 24→import { clearFileSizeCache } from './useFileSize';
 25→
 26→export function useAuth() {
 27→  const navigate = useNavigate();
 28→  const {
 29→    isLoggedIn: coreKitLoggedIn,
 30→    isInitialized: coreKitInitialized,
 31→    isRequiredShare,
 32→    loginWithGoogle: coreKitLoginGoogle,
 33→    loginWithEmailOtp: coreKitLoginEmail,
 34→    loginWithWallet: coreKitLoginWallet,
 35→    getVaultKeypair,
 36→    getPublicKeyHex,
 37→    logout: coreKitLogout,
 38→  } = useCoreKitAuth();
 39→  const { syncStatus } = useCoreKit();
 40→  const {
 41→    accessToken,
 42→    isAuthenticated,
 43→    lastAuthMethod,
 44→    userEmail,
 45→    setAccessToken,
 46→    setLastAuthMethod,
 47→    setUserEmail,
 48→    setVaultKeypair,
 49→    logout: clearAuthState,
 50→  } = useAuthStore();
 51→
 52→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 53→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 54→  const restoringRef = useRef(false);
 55→
 56→  // Stable refs for functions used in the session restoration effect.
 57→  // This prevents the effect from re-firing when function references change.
 58→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 59→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 60→
 61→  // Pending auth state for REQUIRED_SHARE flow
 62→  // Stored so completeRequiredShare() can resume after factor input
 63→  const [pendingCipherboxJwt, setPendingCipherboxJwt] = useState<string | null>(null);
 64→  const [pendingAuthMethod, setPendingAuthMethod] = useState<string | null>(null);
 65→
 66→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 67→
 68→  // Get vault store actions
 69→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 70→
 71→  /**
 72→   * Initialize vault for new users or load existing vault keys.
 73→   * Called after successful backend authentication.
 74→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 75→   */
 76→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 77→    // Get user's secp256k1 keypair from Core Kit TSS export
 78→    const userKeypair = await getVaultKeypair();
 79→
 80→    if (!userKeypair) {
 81→      throw new Error('Failed to get vault keypair from Core Kit');
 82→    }
 83→
 84→    // Store keypair in auth store for crypto operations
 85→    setVaultKeypair(userKeypair);
 86→
 87→    try {
 88→      // Try to fetch existing vault
 89→      const existingVault = await vaultApi.getVault();
 90→
 91→      // Store TEE keys if available
 92→      if (existingVault.teeKeys) {
 93→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 94→      }
 95→
 96→      // Vault exists - decrypt keys and load into store
 97→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 98→      const decryptedVault = await decryptVaultKeys(
 99→        {
100→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
101→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
102→        },
103→        userKeypair.privateKey
104→      );
105→
106→      setVaultKeys({
107→        rootFolderKey: decryptedVault.rootFolderKey,
108→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
109→        rootIpnsName: existingVault.rootIpnsName,
110→        vaultId: existingVault.id,
111→      });
112→    } catch (error) {
113→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
114→
115→      if (is404) {
116→        // New user - initialize vault
117→        console.log(
118→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
119→        );
120→        const newVault = await initializeVault(userKeypair.privateKey);
121→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
122→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
123→
124→        const storedVault = await vaultApi.initVault({
125→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
126→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
127→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
128→          rootIpnsName,
129→        });
130→
131→        if (storedVault.teeKeys) {
132→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
133→        }
134→
135→        setVaultKeys({
136→          rootFolderKey: newVault.rootFolderKey,
137→          rootIpnsKeypair: newVault.rootIpnsKeypair,
138→          rootIpnsName,
139→          vaultId: storedVault.id,
140→          isNewVault: true,
141→        });
142→      } else {
143→        console.error('[useAuth] Failed to load vault:', error);
144→        throw error;
145→      }
146→    }
147→
148→    // Non-blocking device registry initialization (fire-and-forget)
149→    // Placed after vault load so registry failures never block login
150→    void (async () => {
151→      try {
152→        const deviceKeypair = await getOrCreateDeviceIdentity();
153→        const deviceInfo = detectDeviceInfo();
154→        const result = await initializeOrSyncRegistry({
155→          userPrivateKey: userKeypair.privateKey,
156→          userPublicKey: userKeypair.publicKey,
157→          deviceKeypair,
158→          deviceInfo: { ...deviceInfo, ipHash: '' },
159→        });
160→        if (result) {
161→          useDeviceRegistryStore
162→            .getState()
163→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
164→        }
165→      } catch (error) {
166→        console.error('[Auth] Device registry init failed (non-blocking):', error);
167→      }
168→    })();
169→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
170→
171→  /**
172→   * Complete backend authentication after Core Kit login.
173→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
174→   * to the backend with loginType 'corekit'. The backend verifies it against
175→   * its own JWKS since CipherBox is the identity provider.
176→   */
177→  const completeBackendAuth = useCallback(
178→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
179→      // 1. Get real publicKey from Core Kit TSS export
180→      const publicKey = await getPublicKeyHex();
181→      if (!publicKey) {
182→        throw new Error('Failed to get publicKey from Core Kit');
183→      }
184→
185→      // publicKey available for debugging via DevTools if needed
186→
187→      // 2. Authenticate with CipherBox backend
188→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
189→      const response = await authApi.login({
190→        idToken: cipherboxJwt,
191→        publicKey,
192→        loginType: 'corekit',
193→      });
194→
195→      // 3. Store access token (refresh token in HTTP-only cookie)
196→      setAccessToken(response.accessToken);
197→
198→      // 4. Remember auth method for UX
199→      setLastAuthMethod(authMethod);
200→
201→      // 5. Initialize or load vault
202→      await initializeOrLoadVault();
203→    },
204→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
205→  );
206→
207→  /**
208→   * Complete the login flow after REQUIRED_SHARE is resolved.
209→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
210→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
211→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
212→   */
213→  const completeRequiredShare = useCallback(async (): Promise<void> => {
214→    const jwt = pendingCipherboxJwt;
215→    const method = pendingAuthMethod;
216→
217→    if (!jwt || !method) {
218→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
219→    }
220→
221→    // Core Kit should now be LOGGED_IN after inputFactorKey()
222→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
223→    await completeBackendAuth(method, jwt);
224→
225→    // NOW sync Core Kit React state to LOGGED_IN.
226→    // We deliberately delayed this from inputFactorKey() to prevent the session
227→    // restoration effect from firing before backend auth completed.
228→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
229→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
230→    syncStatus();
231→
232→    // Clear pending state
233→    setPendingCipherboxJwt(null);
234→    setPendingAuthMethod(null);
235→
236→    // Navigate to files
237→    navigate('/files');
238→  }, [pendingCipherboxJwt, pendingAuthMethod, completeBackendAuth, syncStatus, navigate]);
239→
240→  /**
241→   * Login with Google OAuth token.
242→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
243→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
244→   */
245→  const loginWithGoogle = useCallback(
246→    async (googleIdToken: string): Promise<void> => {
247→      if (isLoggingIn) return;
248→      setIsLoggingIn(true);
249→      try {
250→        // 1. Core Kit login via CipherBox identity provider
251→        const {
252→          cipherboxJwt,
253→          email,
254→          userId,
255→          status: coreKitStatus,
256→        } = await coreKitLoginGoogle(googleIdToken);
257→
258→        if (coreKitStatus === 'required_share') {
259→          // MFA enabled but device factor missing.
260→          // Store pending auth info for later completion after factor input.
261→          setPendingCipherboxJwt(cipherboxJwt);
262→          setPendingAuthMethod('google');
263→
264→          // Obtain temporary backend access token so the new device can
265→          // call bulletin board API endpoints (device-approval/*).
266→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
267→          // state and we can't export the TSS key yet.
268→          const tempLoginResponse = await authApi.login({
269→            idToken: cipherboxJwt,
270→            publicKey: `pending-core-kit-${userId}`,
271→            loginType: 'corekit',
272→          });
273→          setAccessToken(tempLoginResponse.accessToken);
274→
275→          if (email) {
276→            setUserEmail(email);
277→          }
278→
279→          // Do NOT call completeBackendAuth() or navigate('/files')
280→          // The component tree will see isRequiredShare === true and
281→          // render recovery/approval UI.
282→          return;
283→        }
284→
285→        // Normal path: Core Kit logged in, proceed as before
286→        // 2. Complete backend auth + vault init
287→        await completeBackendAuth('google', cipherboxJwt);
288→
289→        // 3. Store email for UI display (returned from identity endpoint)
290→        if (email) {
291→          setUserEmail(email);
292→        }
293→
294→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
295→      } catch (error) {
296→        console.error('[useAuth] Google login failed:', error);
297→        throw error;
298→      } finally {
299→        setIsLoggingIn(false);
300→      }
301→    },
302→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
303→  );
304→
305→  /**
306→   * Login with Email OTP.
307→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
308→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
309→   */
310→  const loginWithEmail = useCallback(
311→    async (email: string, otp: string): Promise<void> => {
312→      if (isLoggingIn) return;
313→      setIsLoggingIn(true);
314→      try {
315→        // 1. Core Kit login via CipherBox identity provider
316→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
317→
318→        if (coreKitStatus === 'required_share') {
319→          setPendingCipherboxJwt(cipherboxJwt);
320→          setPendingAuthMethod('email');
321→
322→          const tempLoginResponse = await authApi.login({
323→            idToken: cipherboxJwt,
324→            publicKey: `pending-core-kit-${userId}`,
325→            loginType: 'corekit',
326→          });
327→          setAccessToken(tempLoginResponse.accessToken);
328→          setUserEmail(email);
329→          return;
330→        }
331→
332→        // Normal path
333→        await completeBackendAuth('email', cipherboxJwt);
334→        setUserEmail(email);
335→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
336→      } catch (error) {
337→        console.error('[useAuth] Email login failed:', error);
338→        throw error;
339→      } finally {
340→        setIsLoggingIn(false);
341→      }
342→    },
343→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
344→  );
345→
346→  /**
347→   * Login with Wallet (SIWE).
348→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
349→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
350→   */
351→  const loginWithWallet = useCallback(
352→    async (cipherboxJwt: string, userId: string): Promise<void> => {
353→      if (isLoggingIn) return;
354→      setIsLoggingIn(true);
355→      try {
356→        // 1. Core Kit login via CipherBox identity provider
357→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
358→
359→        if (coreKitStatus === 'required_share') {
360→          setPendingCipherboxJwt(cipherboxJwt);
361→          setPendingAuthMethod('wallet');
362→
363→          const tempLoginResponse = await authApi.login({
364→            idToken: cipherboxJwt,
365→            publicKey: `pending-core-kit-${userId}`,
366→            loginType: 'corekit',
367→          });
368→          setAccessToken(tempLoginResponse.accessToken);
369→          return;
370→        }
371→
372→        // Normal path
373→        await completeBackendAuth('wallet', cipherboxJwt);
374→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
375→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
376→        // inside it may still be pending. An explicit navigate here would fire AFTER
377→        // vault init completes — by which point the user may have navigated away from
378→        // the login page, causing a disruptive late redirect.
379→      } catch (error) {
380→        console.error('[useAuth] Wallet login failed:', error);
381→        throw error;
382→      } finally {
383→        setIsLoggingIn(false);
384→      }
385→    },
386→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
387→  );
388→
389→  /**
390→   * Legacy login() for backward compatibility with AuthButton.
391→   * With Core Kit, login requires specifying the auth method.
392→   * This will be replaced by the new Login UI in Plan 04.
393→   */
394→  const login = useCallback(async () => {
395→    // Plan 04 will build the new login UI with method selection.
396→    // For now, this is a no-op placeholder that AuthButton calls.
397→    console.warn(
398→      '[useAuth] login() called without method -- ' +
399→        'use loginWithGoogle() or loginWithEmail() instead. ' +
400→        'Plan 04 will provide the new Login UI.'
401→    );
402→  }, []);
403→
404→  // Complete logout: Backend -> Core Kit -> Clear state
405→  const logout = useCallback(async () => {
406→    if (isLoggingOut) return;
407→
408→    setIsLoggingOut(true);
409→    try {
410→      // 1. Call backend logout (clears cookie)
411→      if (accessToken) {
412→        try {
413→          await authApi.logout();
414→        } catch {
415→          // Ignore errors -- we'll clear state anyway
416→        }
417→      }
418→
419→      // 2. Logout Core Kit (clears session from localStorage)
420→      await coreKitLogout();
421→
422→      // 3. Clear local state
423→      // [SECURITY: HIGH-02] Clear vault and folder stores
424→      // BEFORE auth state to zero crypto keys from memory
425→      useFolderStore.getState().clearFolders();
426→      useVaultStore.getState().clearVaultKeys();
427→      useSyncStore.getState().reset();
428→      useDeviceRegistryStore.getState().clearRegistry();
429→      useMfaStore.getState().reset();
430→      clearFileSizeCache();
431→      clearAuthState();
432→
433→      // 4. Clear pending REQUIRED_SHARE state
434→      setPendingCipherboxJwt(null);
435→      setPendingAuthMethod(null);
436→
437→      // 5. Navigate to login
438→      navigate('/');
439→    } catch (error) {
440→      console.error('[useAuth] Logout failed:', error);
441→      // Still clear state even if backend fails
442→      useFolderStore.getState().clearFolders();
443→      useVaultStore.getState().clearVaultKeys();
444→      useSyncStore.getState().reset();
445→      useDeviceRegistryStore.getState().clearRegistry();
446→      useMfaStore.getState().reset();
447→      clearFileSizeCache();
448→      clearAuthState();
449→      setPendingCipherboxJwt(null);
450→      setPendingAuthMethod(null);
451→      navigate('/');
452→    } finally {
453→      setIsLoggingOut(false);
454→    }
455→  }, [accessToken, coreKitLogout, clearAuthState, navigate, isLoggingOut]);
456→
457→  // Keep function refs up-to-date for use in session restoration effect.
458→  // Using refs prevents the effect from re-firing when function identities change.
459→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
460→  coreKitLogoutRef.current = coreKitLogout;
461→
462→  // Session restoration: if Core Kit restores a session from localStorage
463→  // on init, we have LOGGED_IN status without going through login flow.
464→  // Complete backend auth + vault loading.
465→  useEffect(() => {
466→    const restoreSession = async () => {
467→      // Only restore if Core Kit has a session but we don't have
468→      // a backend access token yet
469→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
470→        restoringRef.current = true;
471→        setIsLoggingIn(true);
472→        try {
473→          // Try to refresh using the HTTP-only cookie first
474→          const response = await authApi.refresh();
475→          setAccessToken(response.accessToken);
476→
477→          // Restore email from backend if available
478→          if (response.email) {
479→            setUserEmail(response.email);
480→          }
481→
482→          // Load vault keys from Core Kit keypair
483→          await initializeOrLoadVaultRef.current?.();
484→        } catch {
485→          // No valid backend session -- user needs to re-login
486→          // Core Kit session exists but backend cookie expired
487→          // Clear Core Kit session to avoid inconsistent state
488→          try {
489→            await coreKitLogoutRef.current?.();
490→          } catch {
491→            // Ignore logout errors during cleanup
492→          }
493→        } finally {
494→          restoringRef.current = false;
495→          setIsLoggingIn(false);
496→        }
497→      }
498→    };
499→    restoreSession();
500→  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);
501→
502→  return {
503→    isLoading,
504→    isAuthenticated,
505→    isRequiredShare,
506→    lastAuthMethod,
507→    userEmail,
508→    pendingAuthMethod,
509→    login,
510→    loginWithGoogle,
511→    loginWithEmail,
512→    loginWithWallet,
513→    completeRequiredShare,
514→    logout,
515→  };
516→}
