  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useDeviceApproval, type ApprovalStatus } from '../../hooks/useDeviceApproval';
  3→import { useAuthStore } from '../../stores/auth.store';
  4→
  5→type DeviceWaitingScreenProps = {
  6→  onRecoveryFallback: () => void;
  7→  onApprovalComplete: () => void;
  8→};
  9→
 10→const APPROVAL_TTL_MS = 5 * 60 * 1000; // 5 minutes
 11→const COUNTDOWN_WARNING_MS = 3 * 60 * 1000; // 3 minutes remaining
 12→
 13→/**
 14→ * Full-screen waiting component shown when a new device is in
 15→ * REQUIRED_SHARE state. Creates a bulletin board approval request
 16→ * and polls for a response from an existing device.
 17→ *
 18→ * Displays a spinner, countdown timer, and a fallback link to
 19→ * use a recovery phrase instead.
 20→ */
 21→export function DeviceWaitingScreen({
 22→  onRecoveryFallback,
 23→  onApprovalComplete,
 24→}: DeviceWaitingScreenProps) {
 25→  const { requestApproval, cancelRequest, approvalStatus, approvalError } = useDeviceApproval();
 26→  const accessToken = useAuthStore((s) => s.accessToken);
 27→
 28→  const [countdown, setCountdown] = useState(APPROVAL_TTL_MS);
 29→  const startTimeRef = useRef<number>(Date.now());
 30→  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);
 31→  const requestFiredRef = useRef(false);
 32→
 33→  // Start the approval request once the temp access token is available.
 34→  // The token is obtained asynchronously in loginWithGoogle/Email/Wallet
 35→  // AFTER syncStatus() sets isRequiredShare=true, so this component may
 36→  // mount before the token is stored. We wait for it to avoid a 401.
 37→  //
 38→  // Cleanup is paired with setup for React StrictMode safety: in dev mode,
 39→  // the simulated unmount cancels the request and resets the guard ref,
 40→  // allowing the second mount to re-create a fresh request with a new
 41→  // ephemeral keypair.
 42→  useEffect(() => {
 43→    if (!accessToken || requestFiredRef.current) return;
 44→    requestFiredRef.current = true;
 45→
 46→    // Clear any existing interval before starting a new one (defensive against retry re-trigger)
 47→    if (countdownRef.current) {
 48→      clearInterval(countdownRef.current);
 49→    }
 50→
 51→    startTimeRef.current = Date.now();
 52→    requestApproval();
 53→
 54→    // Countdown timer
 55→    countdownRef.current = setInterval(() => {
 56→      const elapsed = Date.now() - startTimeRef.current;
 57→      const remaining = Math.max(0, APPROVAL_TTL_MS - elapsed);
 58→      setCountdown(remaining);
 59→    }, 1000);
 60→
 61→    return () => {
 62→      if (countdownRef.current) {
 63→        clearInterval(countdownRef.current);
 64→        countdownRef.current = null;
 65→      }
 66→      requestFiredRef.current = false;
 67→      cancelRequest();
 68→    };
 69→  }, [accessToken, requestApproval, cancelRequest]);
 70→
 71→  // Auto-complete when approval succeeds
 72→  useEffect(() => {
 73→    if (approvalStatus === 'approved') {
 74→      onApprovalComplete();
 75→    }
 76→  }, [approvalStatus, onApprovalComplete]);
 77→
 78→  const handleRetry = useCallback(() => {
 79→    requestFiredRef.current = false;
 80→    startTimeRef.current = Date.now();
 81→    setCountdown(APPROVAL_TTL_MS);
 82→    requestApproval();
 83→  }, [requestApproval]);
 84→
 85→  const minutes = Math.floor(countdown / 60000);
 86→  const seconds = Math.floor((countdown % 60000) / 1000);
 87→  const timeDisplay = `${minutes}:${seconds.toString().padStart(2, '0')}`;
 88→  const isWarning = countdown <= COUNTDOWN_WARNING_MS && countdown > 0;
 89→
 90→  return (
 91→    <div className="device-waiting" data-testid="device-waiting">
 92→      <div className="device-waiting-card">
 93→        <h2 className="device-waiting-title">{'// waiting for device approval'}</h2>
 94→
 95→        {renderContent(approvalStatus, {
 96→          timeDisplay,
 97→          isWarning,
 98→          countdown,
 99→          approvalError,
100→          onRecoveryFallback,
101→          handleRetry,
102→        })}
103→      </div>
104→    </div>
105→  );
106→}
107→
108→function renderContent(
109→  status: ApprovalStatus,
110→  props: {
111→    timeDisplay: string;
112→    isWarning: boolean;
113→    countdown: number;
114→    approvalError: string | null;
115→    onRecoveryFallback: () => void;
116→    handleRetry: () => void;
117→  }
118→) {
119→  const { timeDisplay, isWarning, countdown, approvalError, onRecoveryFallback, handleRetry } =
120→    props;
121→
122→  if (status === 'denied') {
123→    return (
124→      <div className="device-waiting-content">
125→        <div
126→          className="device-waiting-status-message device-waiting-denied"
127→          data-testid="device-waiting-status"
128→        >
129→          Request was denied by another device.
130→        </div>
131→        <div className="device-waiting-actions">
132→          <button
133→            type="button"
134→            className="device-waiting-btn"
135→            onClick={handleRetry}
136→            data-testid="device-waiting-retry"
137→          >
138→            --retry
139→          </button>
140→          <button
141→            type="button"
142→            className="device-waiting-link"
143→            onClick={onRecoveryFallback}
144→            data-testid="device-waiting-recovery-link"
145→          >
146→            use recovery phrase instead
147→          </button>
148→        </div>
149→      </div>
150→    );
151→  }
152→
153→  if (status === 'expired') {
154→    return (
155→      <div className="device-waiting-content">
156→        <div
157→          className="device-waiting-status-message device-waiting-expired"
158→          data-testid="device-waiting-status"
159→        >
160→          Request expired. No device responded within the time limit.
161→        </div>
162→        <div className="device-waiting-actions">
163→          <button
164→            type="button"
165→            className="device-waiting-btn"
166→            onClick={handleRetry}
167→            data-testid="device-waiting-retry"
168→          >
169→            --retry
170→          </button>
171→          <button
172→            type="button"
173→            className="device-waiting-link"
174→            onClick={onRecoveryFallback}
175→            data-testid="device-waiting-recovery-link"
176→          >
177→            use recovery phrase instead
178→          </button>
179→        </div>
180→      </div>
181→    );
182→  }
183→
184→  if (status === 'error') {
185→    return (
186→      <div className="device-waiting-content">
187→        <div
188→          className="device-waiting-status-message device-waiting-error"
189→          data-testid="device-waiting-status"
190→        >
191→          {approvalError || 'An error occurred.'}
192→        </div>
193→        <div className="device-waiting-actions">
194→          <button
195→            type="button"
196→            className="device-waiting-btn"
197→            onClick={handleRetry}
198→            data-testid="device-waiting-retry"
199→          >
200→            --retry
201→          </button>
202→          <button
203→            type="button"
204→            className="device-waiting-link"
205→            onClick={onRecoveryFallback}
206→            data-testid="device-waiting-recovery-link"
207→          >
208→            use recovery phrase instead
209→          </button>
210→        </div>
211→      </div>
212→    );
213→  }
214→
215→  if (status === 'completing') {
216→    return (
217→      <div className="device-waiting-content">
218→        <span className="device-waiting-spinner" aria-hidden="true" />
219→        <p className="device-waiting-text">Approval received. Completing login...</p>
220→      </div>
221→    );
222→  }
223→
224→  // Default: requesting/pending
225→  return (
226→    <div className="device-waiting-content">
227→      <span className="device-waiting-spinner" aria-hidden="true" />
228→      <p className="device-waiting-text">
229→        Request sent to your other devices. Open CipherBox on an authorized device to approve this
230→        login.
231→      </p>
232→      <div
233→        className={`device-waiting-countdown ${isWarning ? 'warning' : ''}`}
234→        aria-label={`Time remaining: ${timeDisplay}`}
235→        data-testid="device-waiting-countdown"
236→      >
237→        {countdown > 0 ? timeDisplay : 'expired'}
238→      </div>
239→      <button
240→        type="button"
241→        className="device-waiting-link"
242→        onClick={onRecoveryFallback}
243→        data-testid="device-waiting-recovery-link"
244→      >
245→        use recovery phrase instead
246→      </button>
247→    </div>
248→  );
249→}
