await waitForDeviceApproval(primaryPage, { timeout: 60_000 });

// DEBUG: Capture console output from both pages
const primaryLogs: string[] = [];
const pageBLogs: string[] = [];
primaryPage.on('console', (msg) => {
  if (msg.type() === 'error' || msg.text().includes('[') || msg.text().includes('approve')) {
    primaryLogs.push(`[primary ${msg.type()}] ${msg.text()}`);
  }
});
pageB.on('console', (msg) => {
  if (msg.type() === 'error' || msg.text().includes('[') || msg.text().includes('approve')) {
    pageBLogs.push(`[pageB ${msg.type()}] ${msg.text()}`);
  }
});

// 6. Approve the request on primary page
//    Click the approve button directly and DON'T wait for modal dismissal
//    (modal may stay due to polling race; verify via context B redirect instead)
const approveBtn = primaryPage.locator('[data-testid="device-approval-approve"]');
await approveBtn.waitFor({ state: 'visible', timeout: 5_000 });
await approveBtn.click();

// Give the approve action time to process
await primaryPage.waitForTimeout(3_000);

// DEBUG: Dump logs
console.log('--- PRIMARY LOGS ---');
primaryLogs.forEach((l) => console.log(l));
console.log('--- PAGE B LOGS ---');
pageBLogs.forEach((l) => console.log(l));

// Check primary page for error text
const modalError = primaryPage.locator('.device-approval-warning[role="alert"]');
if (await modalError.isVisible()) {
  const errText = await modalError.textContent();
  console.log(`MODAL ERROR: ${errText}`);
}

// Check context B state
const pageBUrl = pageB.url();
console.log(`PageB URL: ${pageBUrl}`);
