if (pageBState) {
  const statusText = await pageB.locator('[data-testid="device-waiting-status"]').textContent();
  console.log(`PageB status: ${statusText}`);
}

// 7. Wait for context B to complete login → redirect to /files
await pageB.waitForURL('**/files', { timeout: 60_000 });

