 1→import { Module } from '@nestjs/common';
 2→import { TypeOrmModule } from '@nestjs/typeorm';
 3→import { DeviceApproval } from './device-approval.entity';
 4→import { DeviceApprovalService } from './device-approval.service';
 5→import { DeviceApprovalController } from './device-approval.controller';
 6→
 7→@Module({
 8→  imports: [TypeOrmModule.forFeature([DeviceApproval])],
