  1→/**
  2→ * useDeviceApproval Hook
  3→ *
  4→ * Manages the full lifecycle for BOTH sides of the cross-device approval flow:
  5→ *
  6→ * **New device (requester):**
  7→ * - Generate ephemeral secp256k1 keypair
  8→ * - Create bulletin board request
  9→ * - Poll for approval status
 10→ * - On approval: ECIES-decrypt factor key, inputFactorKey, create device factor
 11→ *
 12→ * **Existing device (approver):**
 13→ * - Poll for pending approval requests
 14→ * - Approve: ECIES-encrypt current factor key with requester's ephemeral public key
 15→ * - Deny: mark request as denied
 16→ */
 17→
 18→import { useCallback, useEffect, useRef, useState } from 'react';
 19→import * as secp256k1 from '@noble/secp256k1';
 20→import {
 21→  generateFactorKey,
 22→  TssShareType,
 23→  FactorKeyTypeShareDescription,
 24→} from '@web3auth/mpc-core-kit';
 25→import { wrapKey, unwrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 26→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
 27→import { useMfa } from './useMfa';
 28→import { useVisibility } from './useVisibility';
 29→import { useAuth } from './useAuth';
 30→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 31→import { detectDeviceInfo } from '../lib/device/info';
 32→import {
 33→  deviceApprovalApi,
 34→  type ApprovalStatusResponse,
 35→  type PendingApproval,
 36→} from '../services/device-approval.service';
 37→
 38→export type ApprovalStatus =
 39→  | 'idle'
 40→  | 'requesting'
 41→  | 'pending'
 42→  | 'approved'
 43→  | 'denied'
 44→  | 'expired'
 45→  | 'completing'
 46→  | 'error';
 47→
 48→export function useDeviceApproval() {
 49→  const { coreKit } = useCoreKit();
 50→  const { inputFactorKey } = useMfa();
 51→  const { completeRequiredShare } = useAuth();
 52→  const isVisible = useVisibility();
 53→
 54→  // --- New device (requester) state ---
 55→  const [approvalStatus, setApprovalStatus] = useState<ApprovalStatus>('idle');
 56→  const [approvalError, setApprovalError] = useState<string | null>(null);
 57→  const requestIdRef = useRef<string | null>(null);
 58→  const ephemeralPrivKeyRef = useRef<Uint8Array | null>(null);
 59→  const requesterPollRef = useRef<ReturnType<typeof setInterval> | null>(null);
 60→
 61→  // --- Existing device (approver) state ---
 62→  const [pendingRequests, setPendingRequests] = useState<PendingApproval[]>([]);
 63→  const isPollingPendingRef = useRef(false);
 64→  const approverPollRef = useRef<ReturnType<typeof setInterval> | null>(null);
 65→  // Track recently approved/denied request IDs to filter out stale polling responses.
 66→  // Without this, the 5s polling interval can re-add a request that was just handled
 67→  // if the poll response was already in-flight when the respond API call completed.
 68→  const handledRequestIdsRef = useRef<Set<string>>(new Set());
 69→
 70→  /**
 71→   * Zero-fill and clear ephemeral private key from memory.
 72→   */
 73→  const clearEphemeralKey = useCallback(() => {
 74→    if (ephemeralPrivKeyRef.current) {
 75→      ephemeralPrivKeyRef.current.fill(0);
 76→      ephemeralPrivKeyRef.current = null;
 77→    }
 78→  }, []);
 79→
 80→  /**
 81→   * Stop requester polling.
 82→   */
 83→  const stopRequesterPolling = useCallback(() => {
 84→    if (requesterPollRef.current) {
 85→      clearInterval(requesterPollRef.current);
 86→      requesterPollRef.current = null;
 87→    }
 88→  }, []);
 89→
 90→  /**
 91→   * Stop approver polling.
 92→   */
 93→  const stopApproverPolling = useCallback(() => {
 94→    if (approverPollRef.current) {
 95→      clearInterval(approverPollRef.current);
 96→      approverPollRef.current = null;
 97→    }
 98→    isPollingPendingRef.current = false;
 99→  }, []);
100→
101→  // =========================================================================
102→  // NEW DEVICE SIDE (REQUESTER)
103→  // =========================================================================
104→
105→  /**
106→   * Handle a successful approval: decrypt factor key, input it, create device factor.
107→   */
108→  const handleApprovalSuccess = useCallback(
109→    async (encryptedFactorKeyHex: string) => {
110→      setApprovalStatus('completing');
111→
112→      try {
113→        const ephPrivKey = ephemeralPrivKeyRef.current;
114→        if (!ephPrivKey) {
115→          throw new Error('Ephemeral private key not available');
116→        }
117→        if (!coreKit) {
118→          throw new Error('Core Kit not initialized');
119→        }
120→
121→        // 1. ECIES-decrypt the factor key
122→        const encrypted = hexToBytes(encryptedFactorKeyHex);
123→        const factorKeyBytes = await unwrapKey(encrypted, ephPrivKey);
124→        const factorKeyHex = bytesToHex(factorKeyBytes);
125→        factorKeyBytes.fill(0); // Zero-fill decrypted key material after conversion
126→
127→        // 2. Input the factor key to complete Core Kit login
128→        await inputFactorKey(factorKeyHex);
129→
130→        // 3. Create device factor for this new device
131→        const newDeviceFactor = generateFactorKey();
132→        await coreKit.createFactor({
133→          shareType: TssShareType.DEVICE,
134→          factorKey: newDeviceFactor.private,
135→          shareDescription: FactorKeyTypeShareDescription.DeviceShare,
136→        });
137→        await coreKit.setDeviceFactor(newDeviceFactor.private);
138→        await coreKit.commitChanges();
139→
140→        // 4. Clean up ephemeral key
141→        clearEphemeralKey();
142→
143→        // 5. Complete the login flow
144→        await completeRequiredShare();
145→
146→        setApprovalStatus('approved');
147→      } catch (err) {
148→        stopRequesterPolling();
149→        clearEphemeralKey();
150→        setApprovalError(err instanceof Error ? err.message : 'Failed to complete approval');
151→        setApprovalStatus('error');
152→      }
153→    },
154→    [coreKit, inputFactorKey, completeRequiredShare, clearEphemeralKey, stopRequesterPolling]
155→  );
156→
157→  /**
158→   * Start polling for approval status (new device side).
159→   */
160→  const startRequesterPolling = useCallback(
161→    (requestId: string) => {
162→      stopRequesterPolling();
163→
164→      const poll = async () => {
165→        // Separate network fetch from success handling so network errors
166→        // don't swallow failures from handleApprovalSuccess/completeRequiredShare
167→        let result: ApprovalStatusResponse;
168→        try {
169→          result = await deviceApprovalApi.getStatus(requestId);
170→        } catch {
171→          // Network error -- continue polling, don't crash
172→          return;
173→        }
174→
175→        if (result.status === 'approved' && result.encryptedFactorKey) {
176→          stopRequesterPolling();
177→          await handleApprovalSuccess(result.encryptedFactorKey);
178→        } else if (result.status === 'denied') {
179→          stopRequesterPolling();
180→          clearEphemeralKey();
181→          setApprovalStatus('denied');
182→        } else if (result.status === 'expired') {
183→          stopRequesterPolling();
184→          clearEphemeralKey();
185→          setApprovalStatus('expired');
186→        }
187→        // 'pending' -> continue polling
188→      };
189→
190→      requesterPollRef.current = setInterval(poll, 3000);
191→      // Fire immediately
192→      void poll();
193→    },
194→    [stopRequesterPolling, handleApprovalSuccess, clearEphemeralKey]
195→  );
196→
197→  /**
198→   * Create an approval request on the bulletin board (new device side).
199→   * Generates an ephemeral keypair and starts polling.
200→   */
201→  const requestApproval = useCallback(async () => {
202→    setApprovalStatus('requesting');
203→    setApprovalError(null);
204→
205→    try {
206→      // 1. Generate ephemeral secp256k1 keypair
207→      // keygen() returns compressed pubkey (33 bytes) by default, but the
208→      // backend DTO requires uncompressed (65 bytes = 130 hex chars).
209→      const ephemeral = secp256k1.keygen();
210→      ephemeralPrivKeyRef.current = ephemeral.secretKey;
211→      const uncompressedPubKey = secp256k1.getPublicKey(ephemeral.secretKey, false);
212→      const ephemeralPubKeyHex = bytesToHex(uncompressedPubKey);
213→
214→      // 2. Get device identity
215→      const deviceIdentity = await getOrCreateDeviceIdentity();
216→
217→      // 3. Get device name
218→      const deviceInfo = detectDeviceInfo();
219→
220→      // 4. Create request on bulletin board
221→      const { requestId } = await deviceApprovalApi.createRequest({
222→        deviceId: deviceIdentity.deviceId,
223→        deviceName: deviceInfo.name,
224→        ephemeralPublicKey: ephemeralPubKeyHex,
225→      });
226→
227→      requestIdRef.current = requestId;
228→      setApprovalStatus('pending');
229→
230→      // 5. Start polling for response
231→      startRequesterPolling(requestId);
232→    } catch (err) {
233→      clearEphemeralKey();
234→      setApprovalError(err instanceof Error ? err.message : 'Failed to create approval request');
235→      setApprovalStatus('error');
236→    }
237→  }, [startRequesterPolling, clearEphemeralKey]);
238→
239→  /**
240→   * Cancel the pending approval request (new device side).
241→   * Also called when recovery phrase is used instead (RESEARCH.md Pitfall 5).
242→   */
243→  const cancelRequest = useCallback(async () => {
244→    stopRequesterPolling();
245→
246→    if (requestIdRef.current) {
247→      try {
248→        await deviceApprovalApi.cancel(requestIdRef.current);
249→      } catch {
250→        // Best-effort cleanup -- request may already be expired/cancelled
251→      }
252→      requestIdRef.current = null;
253→    }
254→
255→    clearEphemeralKey();
256→    setApprovalStatus('idle');
257→  }, [stopRequesterPolling, clearEphemeralKey]);
258→
259→  // =========================================================================
260→  // EXISTING DEVICE SIDE (APPROVER)
261→  // =========================================================================
262→
263→  /**
264→   * Start polling for pending approval requests (existing device side).
265→   */
266→  const pollPendingRequests = useCallback(() => {
267→    if (isPollingPendingRef.current) return;
268→    isPollingPendingRef.current = true;
269→
270→    const poll = async () => {
271→      try {
272→        const pending = await deviceApprovalApi.getPending();
273→        // Filter out requests that were recently approved/denied locally
274→        // to prevent stale in-flight poll responses from re-adding them.
275→        const handled = handledRequestIdsRef.current;
276→        const filtered = handled.size > 0
277→          ? pending.filter((r) => !handled.has(r.requestId!))
278→          : pending;
279→        setPendingRequests(filtered);
280→      } catch {
281→        // Network error -- continue polling
282→      }
283→    };
284→
285→    // Poll every 5 seconds
286→    approverPollRef.current = setInterval(poll, 5000);
287→    // Fire immediately
288→    void poll();
289→  }, []);
290→
291→  /**
292→   * Approve a pending request: ECIES-encrypt current factor key with
293→   * the requester's ephemeral public key and send the response.
294→   */
295→  const approveRequest = useCallback(
296→    async (requestId: string, ephemeralPublicKeyHex: string) => {
297→      if (!coreKit) throw new Error('Core Kit not initialized');
298→
299→      // 1. Get current factor key
300→      const factorKeyResult = coreKit.getCurrentFactorKey();
301→      if (!factorKeyResult?.factorKey) {
302→        throw new Error('No active factor key available to share');
303→      }
304→      const factorKeyHex = factorKeyResult.factorKey.toString('hex').padStart(64, '0');
305→      const factorKeyBytes = hexToBytes(factorKeyHex);
306→
307→      // 2. ECIES-encrypt with the requester's ephemeral public key
308→      const ephemeralPubKey = hexToBytes(ephemeralPublicKeyHex);
309→      const encrypted = await wrapKey(factorKeyBytes, ephemeralPubKey);
310→      factorKeyBytes.fill(0); // Zero-fill factor key bytes after wrapping
311→
312→      // 3. Get current device ID for tracking
313→      const deviceIdentity = await getOrCreateDeviceIdentity();
314→
315→      // 4. Send response
316→      await deviceApprovalApi.respond(requestId, {
317→        action: 'approve',
318→        encryptedFactorKey: bytesToHex(encrypted),
319→        respondedByDeviceId: deviceIdentity.deviceId,
320→      });
321→
322→      // 5. Remove from pending list and mark as handled to prevent
323→      //    stale polling responses from re-adding it
324→      handledRequestIdsRef.current.add(requestId);
325→      setPendingRequests((prev) => prev.filter((r) => r.requestId !== requestId));
326→    },
327→    [coreKit]
328→  );
329→
330→  /**
331→   * Deny a pending approval request.
332→   */
333→  const denyRequest = useCallback(async (requestId: string) => {
334→    // Get current device ID for tracking
335→    const deviceIdentity = await getOrCreateDeviceIdentity();
336→
337→    await deviceApprovalApi.respond(requestId, {
338→      action: 'deny',
339→      respondedByDeviceId: deviceIdentity.deviceId,
340→    });
341→
342→    // Remove from pending list and mark as handled
343→    handledRequestIdsRef.current.add(requestId);
344→    setPendingRequests((prev) => prev.filter((r) => r.requestId !== requestId));
345→  }, []);
346→
347→  // =========================================================================
348→  // VISIBILITY-BASED POLLING CONTROL (approver)
349→  // =========================================================================
350→
351→  // Pause/resume approver polling based on tab visibility
352→  useEffect(() => {
353→    if (!isPollingPendingRef.current) return;
354→
355→    if (isVisible) {
356→      // Resume polling when tab becomes visible
357→      if (!approverPollRef.current) {
358→        const poll = async () => {
359→          try {
360→            const pending = await deviceApprovalApi.getPending();
361→            const handled = handledRequestIdsRef.current;
362→            const filtered = handled.size > 0
363→              ? pending.filter((r) => !handled.has(r.requestId!))
364→              : pending;
365→            setPendingRequests(filtered);
366→          } catch {
367→            // Network error -- continue polling
368→          }
369→        };
370→        approverPollRef.current = setInterval(poll, 5000);
371→        void poll();
372→      }
373→    } else {
374→      // Pause polling when tab is hidden
375→      if (approverPollRef.current) {
376→        clearInterval(approverPollRef.current);
377→        approverPollRef.current = null;
378→      }
379→    }
380→  }, [isVisible]);
381→
382→  // =========================================================================
383→  // CLEANUP ON UNMOUNT
384→  // =========================================================================
385→
386→  useEffect(() => {
387→    return () => {
388→      stopRequesterPolling();
389→      stopApproverPolling();
390→      clearEphemeralKey();
391→    };
392→  }, [stopRequesterPolling, stopApproverPolling, clearEphemeralKey]);
393→
394→  return {
395→    // Requester (new device)
396→    requestApproval,
397→    cancelRequest,
398→    approvalStatus,
399→    approvalError,
400→
401→    // Approver (existing device)
402→    pollPendingRequests,
