 26→export function useAuth() {
 27→  const navigate = useNavigate();
 28→  const {
 29→    isLoggedIn: coreKitLoggedIn,
 30→    isInitialized: coreKitInitialized,
 31→    isRequiredShare,
 32→    loginWithGoogle: coreKitLoginGoogle,
 33→    loginWithEmailOtp: coreKitLoginEmail,
 34→    loginWithWallet: coreKitLoginWallet,
 35→    getVaultKeypair,
 36→    getPublicKeyHex,
 37→    logout: coreKitLogout,
 38→  } = useCoreKitAuth();
 39→  const { syncStatus } = useCoreKit();
 40→  const {
 41→    accessToken,
 42→    isAuthenticated,
 43→    lastAuthMethod,
 44→    userEmail,
 45→    setAccessToken,
 46→    setLastAuthMethod,
 47→    setUserEmail,
 48→    setVaultKeypair,
 49→    logout: clearAuthState,
 50→  } = useAuthStore();
 51→
 52→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 53→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 54→  const restoringRef = useRef(false);
 55→
 56→  // Stable refs for functions used in the session restoration effect.
 57→  // This prevents the effect from re-firing when function references change.
 58→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 59→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 60→
 61→  // Pending auth state for REQUIRED_SHARE flow.
 62→  // Stored in Zustand (not useState) so the state is shared across all
 63→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 64→  // via its own useAuth() call.
 65→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 66→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 67→
 68→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 69→
 70→  // Get vault store actions
 71→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 72→
 73→  /**
 74→   * Initialize vault for new users or load existing vault keys.
 75→   * Called after successful backend authentication.
 76→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 77→   */
 78→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 79→    // Get user's secp256k1 keypair from Core Kit TSS export
 80→    const userKeypair = await getVaultKeypair();
 81→
 82→    if (!userKeypair) {
 83→      throw new Error('Failed to get vault keypair from Core Kit');
 84→    }
 85→
 86→    // Store keypair in auth store for crypto operations
 87→    setVaultKeypair(userKeypair);
 88→
 89→    try {
 90→      // Try to fetch existing vault
 91→      const existingVault = await vaultApi.getVault();
 92→
 93→      // Store TEE keys if available
 94→      if (existingVault.teeKeys) {
 95→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 96→      }
 97→
 98→      // Vault exists - decrypt keys and load into store
 99→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
100→      const decryptedVault = await decryptVaultKeys(
101→        {
102→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
103→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
104→        },
105→        userKeypair.privateKey
106→      );
107→
108→      setVaultKeys({
109→        rootFolderKey: decryptedVault.rootFolderKey,
110→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
111→        rootIpnsName: existingVault.rootIpnsName,
112→        vaultId: existingVault.id,
113→      });
114→    } catch (error) {
115→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
116→
117→      if (is404) {
118→        // New user - initialize vault
119→        console.log(
120→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
121→        );
122→        const newVault = await initializeVault(userKeypair.privateKey);
123→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
124→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
125→
126→        const storedVault = await vaultApi.initVault({
127→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
128→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
129→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
130→          rootIpnsName,
131→        });
132→
133→        if (storedVault.teeKeys) {
134→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
135→        }
136→
137→        setVaultKeys({
138→          rootFolderKey: newVault.rootFolderKey,
139→          rootIpnsKeypair: newVault.rootIpnsKeypair,
140→          rootIpnsName,
141→          vaultId: storedVault.id,
142→          isNewVault: true,
143→        });
144→      } else {
145→        console.error('[useAuth] Failed to load vault:', error);
146→        throw error;
147→      }
148→    }
149→
150→    // Non-blocking device registry initialization (fire-and-forget)
151→    // Placed after vault load so registry failures never block login
152→    void (async () => {
153→      try {
154→        const deviceKeypair = await getOrCreateDeviceIdentity();
155→        const deviceInfo = detectDeviceInfo();
156→        const result = await initializeOrSyncRegistry({
157→          userPrivateKey: userKeypair.privateKey,
158→          userPublicKey: userKeypair.publicKey,
159→          deviceKeypair,
160→          deviceInfo: { ...deviceInfo, ipHash: '' },
161→        });
162→        if (result) {
163→          useDeviceRegistryStore
164→            .getState()
165→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
166→        }
167→      } catch (error) {
168→        console.error('[Auth] Device registry init failed (non-blocking):', error);
169→      }
170→    })();
171→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
172→
173→  /**
174→   * Complete backend authentication after Core Kit login.
175→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
176→   * to the backend with loginType 'corekit'. The backend verifies it against
177→   * its own JWKS since CipherBox is the identity provider.
178→   */
179→  const completeBackendAuth = useCallback(
180→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
181→      // 1. Get real publicKey from Core Kit TSS export
182→      const publicKey = await getPublicKeyHex();
183→      if (!publicKey) {
184→        throw new Error('Failed to get publicKey from Core Kit');
185→      }
186→
187→      // publicKey available for debugging via DevTools if needed
188→
189→      // 2. Authenticate with CipherBox backend
190→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
191→      const response = await authApi.login({
192→        idToken: cipherboxJwt,
193→        publicKey,
194→        loginType: 'corekit',
195→      });
196→
197→      // 3. Store access token (refresh token in HTTP-only cookie)
198→      setAccessToken(response.accessToken);
199→
200→      // 4. Remember auth method for UX
201→      setLastAuthMethod(authMethod);
202→
203→      // 5. Initialize or load vault
204→      await initializeOrLoadVault();
205→    },
206→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
207→  );
208→
209→  /**
210→   * Complete the login flow after REQUIRED_SHARE is resolved.
211→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
212→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
213→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
214→   */
215→  const completeRequiredShare = useCallback(async (): Promise<void> => {
216→    // Read directly from Zustand store to get fresh values — this callback
217→    // may be called from useDeviceApproval's useAuth() instance, so we
218→    // can't rely on closure-captured selector values.
219→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
220→
221→    if (!jwt || !method) {
222→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
223→    }
224→
225→    // Core Kit should now be LOGGED_IN after inputFactorKey()
226→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
227→    await completeBackendAuth(method, jwt);
228→
229→    // NOW sync Core Kit React state to LOGGED_IN.
230→    // We deliberately delayed this from inputFactorKey() to prevent the session
231→    // restoration effect from firing before backend auth completed.
232→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
233→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
234→    syncStatus();
235→
236→    // Clear pending state
237→    setPendingAuth(null, null);
238→
239→    // Navigate to files
240→    navigate('/files');
241→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
242→
243→  /**
244→   * Login with Google OAuth token.
245→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
246→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
247→   */
248→  const loginWithGoogle = useCallback(
249→    async (googleIdToken: string): Promise<void> => {
250→      if (isLoggingIn) return;
251→      setIsLoggingIn(true);
252→      try {
253→        // 1. Core Kit login via CipherBox identity provider
254→        const {
255→          cipherboxJwt,
256→          email,
257→          userId,
258→          status: coreKitStatus,
259→        } = await coreKitLoginGoogle(googleIdToken);
260→
261→        if (coreKitStatus === 'required_share') {
262→          // MFA enabled but device factor missing.
263→          // Store pending auth info for later completion after factor input.
264→          setPendingAuth(cipherboxJwt, 'google');
265→
266→          // Obtain temporary backend access token so the new device can
267→          // call bulletin board API endpoints (device-approval/*).
268→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
269→          // state and we can't export the TSS key yet.
270→          const tempLoginResponse = await authApi.login({
271→            idToken: cipherboxJwt,
272→            publicKey: `pending-core-kit-${userId}`,
273→            loginType: 'corekit',
274→          });
275→          setAccessToken(tempLoginResponse.accessToken);
276→
277→          if (email) {
278→            setUserEmail(email);
279→          }
280→
281→          // Do NOT call completeBackendAuth() or navigate('/files')
282→          // The component tree will see isRequiredShare === true and
283→          // render recovery/approval UI.
284→          return;
285→        }
286→
287→        // Normal path: Core Kit logged in, proceed as before
288→        // 2. Complete backend auth + vault init
289→        await completeBackendAuth('google', cipherboxJwt);
290→
291→        // 3. Store email for UI display (returned from identity endpoint)
292→        if (email) {
293→          setUserEmail(email);
294→        }
295→
296→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
297→      } catch (error) {
298→        console.error('[useAuth] Google login failed:', error);
299→        throw error;
300→      } finally {
301→        setIsLoggingIn(false);
302→      }
303→    },
304→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
305→  );
306→
307→  /**
308→   * Login with Email OTP.
309→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
310→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
311→   */
312→  const loginWithEmail = useCallback(
313→    async (email: string, otp: string): Promise<void> => {
314→      if (isLoggingIn) return;
315→      setIsLoggingIn(true);
316→      try {
317→        // 1. Core Kit login via CipherBox identity provider
318→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
319→
320→        if (coreKitStatus === 'required_share') {
321→          setPendingAuth(cipherboxJwt, 'email');
322→
323→          const tempLoginResponse = await authApi.login({
324→            idToken: cipherboxJwt,
325→            publicKey: `pending-core-kit-${userId}`,
326→            loginType: 'corekit',
327→          });
328→          setAccessToken(tempLoginResponse.accessToken);
329→          setUserEmail(email);
330→          return;
331→        }
332→
333→        // Normal path
334→        await completeBackendAuth('email', cipherboxJwt);
335→        setUserEmail(email);
336→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
337→      } catch (error) {
338→        console.error('[useAuth] Email login failed:', error);
339→        throw error;
340→      } finally {
341→        setIsLoggingIn(false);
342→      }
343→    },
344→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
345→  );
346→
347→  /**
348→   * Login with Wallet (SIWE).
349→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
350→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
351→   */
352→  const loginWithWallet = useCallback(
353→    async (cipherboxJwt: string, userId: string): Promise<void> => {
354→      if (isLoggingIn) return;
355→      setIsLoggingIn(true);
356→      try {
357→        // 1. Core Kit login via CipherBox identity provider
358→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
359→
360→        if (coreKitStatus === 'required_share') {
361→          setPendingAuth(cipherboxJwt, 'wallet');
362→
363→          const tempLoginResponse = await authApi.login({
364→            idToken: cipherboxJwt,
365→            publicKey: `pending-core-kit-${userId}`,
366→            loginType: 'corekit',
367→          });
368→          setAccessToken(tempLoginResponse.accessToken);
369→          return;
370→        }
371→
372→        // Normal path
373→        await completeBackendAuth('wallet', cipherboxJwt);
374→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
375→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
376→        // inside it may still be pending. An explicit navigate here would fire AFTER
377→        // vault init completes — by which point the user may have navigated away from
378→        // the login page, causing a disruptive late redirect.
379→      } catch (error) {
380→        console.error('[useAuth] Wallet login failed:', error);
381→        throw error;
382→      } finally {
383→        setIsLoggingIn(false);
384→      }
385→    },
386→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
387→  );
388→
389→  /**
390→   * Legacy login() for backward compatibility with AuthButton.
391→   * With Core Kit, login requires specifying the auth method.
392→   * This will be replaced by the new Login UI in Plan 04.
393→   */
394→  const login = useCallback(async () => {
395→    // Plan 04 will build the new login UI with method selection.
396→    // For now, this is a no-op placeholder that AuthButton calls.
397→    console.warn(
398→      '[useAuth] login() called without method -- ' +
399→        'use loginWithGoogle() or loginWithEmail() instead. ' +
400→        'Plan 04 will provide the new Login UI.'
401→    );
402→  }, []);
403→
404→  // Complete logout: Backend -> Core Kit -> Clear state
405→  const logout = useCallback(async () => {
406→    if (isLoggingOut) return;
407→
408→    setIsLoggingOut(true);
409→    try {
410→      // 1. Call backend logout (clears cookie)
411→      if (accessToken) {
412→        try {
413→          await authApi.logout();
414→        } catch {
415→          // Ignore errors -- we'll clear state anyway
416→        }
417→      }
418→
419→      // 2. Logout Core Kit (clears session from localStorage)
420→      await coreKitLogout();
421→
422→      // 3. Clear local state
423→      // [SECURITY: HIGH-02] Clear vault and folder stores
424→      // BEFORE auth state to zero crypto keys from memory
425→      useFolderStore.getState().clearFolders();
426→      useVaultStore.getState().clearVaultKeys();
427→      useSyncStore.getState().reset();
428→      useDeviceRegistryStore.getState().clearRegistry();
429→      useMfaStore.getState().reset();
430→      clearFileSizeCache();
431→      clearAuthState();
432→
433→      // 4. Navigate to login (pending auth cleared by clearAuthState -> store logout)
434→      navigate('/');
435→    } catch (error) {
436→      console.error('[useAuth] Logout failed:', error);
437→      // Still clear state even if backend fails
438→      useFolderStore.getState().clearFolders();
439→      useVaultStore.getState().clearVaultKeys();
440→      useSyncStore.getState().reset();
441→      useDeviceRegistryStore.getState().clearRegistry();
442→      useMfaStore.getState().reset();
443→      clearFileSizeCache();
444→      clearAuthState();
445→      navigate('/');
446→    } finally {
447→      setIsLoggingOut(false);
448→    }
449→  }, [accessToken, coreKitLogout, clearAuthState, navigate, isLoggingOut]);
450→
451→  // Keep function refs up-to-date for use in session restoration effect.
452→  // Using refs prevents the effect from re-firing when function identities change.
453→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
454→  coreKitLogoutRef.current = coreKitLogout;
455→
456→  // Session restoration: if Core Kit restores a session from localStorage
457→  // on init, we have LOGGED_IN status without going through login flow.
458→  // Complete backend auth + vault loading.
459→  useEffect(() => {
460→    const restoreSession = async () => {
461→      // Only restore if Core Kit has a session but we don't have
462→      // a backend access token yet
463→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
464→        restoringRef.current = true;
465→        setIsLoggingIn(true);
466→        try {
467→          // Try to refresh using the HTTP-only cookie first
468→          const response = await authApi.refresh();
469→          setAccessToken(response.accessToken);
470→
471→          // Restore email from backend if available
472→          if (response.email) {
473→            setUserEmail(response.email);
474→          }
475→
476→          // Load vault keys from Core Kit keypair
477→          await initializeOrLoadVaultRef.current?.();
478→        } catch {
479→          // No valid backend session -- user needs to re-login
480→          // Core Kit session exists but backend cookie expired
481→          // Clear Core Kit session to avoid inconsistent state
482→          try {
483→            await coreKitLogoutRef.current?.();
484→          } catch {
485→            // Ignore logout errors during cleanup
486→          }
487→        } finally {
488→          restoringRef.current = false;
489→          setIsLoggingIn(false);
490→        }
491→      }
492→    };
493→    restoreSession();
494→  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);
495→
496→  return {
497→    isLoading,
498→    isAuthenticated,
499→    isRequiredShare,
500→    lastAuthMethod,
501→    userEmail,
502→    pendingAuthMethod,
503→    login,
504→    loginWithGoogle,
505→    loginWithEmail,
506→    loginWithWallet,
507→    completeRequiredShare,
508→    logout,
509→  };
510→}
